## Why This Problem Is Asked
This question evaluates understanding of dynamic programming on prefixes with a non-crossing pairing constraint. The core challenge is encoding the no-crossing condition by considering the last pair ending at position i with its left partner p.

## Key Concepts
- **DP on prefixes**: Extra dimension tracks the number of pairs formed
- **Non-crossing constraint**: Enforced by pairing i with p < i and using dp[p-1][t-1], which ensures all pairs lie completely to the left of p
- **Reconstruction**: Requires storing backpointers to output the actual pairs
- **Complexity**: Time O(n²k), Space O(nk)

## Code Example
```javascript
function maxPairs(A, k) {
  const n = A.length;
  const NEG = -Infinity;
  const dp = Array.from({ length: n + 1 }, () => Array(k + 1).fill(NEG));
  const prev = Array.from({ length: n + 1 }, () => Array(k + 1).fill(null));

  for (let i = 0; i <= n; i++) dp[i][0] = 0;

  for (let i = 1; i <= n; i++) {
    for (let t = 1; t <= k; t++) {
      dp[i][t] = dp[i - 1][t];
      prev[i][t] = { skip: true };

      for (let p = 1; p < i; p++) {
        const val = dp[p - 1][t - 1] + A[p - 1] * A[i - 1];
        if (val > dp[i][t]) {
          dp[i][t] = val;
          prev[i][t] = { skip: false, p };
        }
      }
    }
  }

  const pairs = [];
  let i = n, t = k;
  while (i > 0 && t > 0) {
    if (prev[i][t].skip) {
      i--;
    } else {
      const p = prev[i][t].p;
      pairs.push([p, i]);
      i = p - 1;
      t--;
    }
  }

  return { value: dp[n][k], pairs: pairs.reverse() };
}
```

## Why This Is Asked
Tests ability to combine subarray maxima with partition DP, requiring both maximization and reconstruction of multiple intervals. It exercises careful indexing and boundary handling.

## Key Concepts
- Non-overlapping subarrays with a cap k
- Precomputation of maxSub for O(1) subarray maxima
- 2D DP with reconstruction pointers
- Time/space tradeoffs and edge cases (k=0, equal values)

## Code Example
```javascript
function maxValueWithKSubarrays(A, k) {
  const n = A.length;
  const maxSub = Array.from({length: n}, () => Array(n).fill(0));
  for (let l = 0; l < n; l++) {
    let m = -Infinity;
    for (let r = l; r < n; r++) {
      m = Math.max(m, A[r]);
      maxSub[l][r] = m;
    }
  }
  const dp = Array.from({length: n+1}, () => Array(k+1).fill(0));
  const take = Array.from({length: n+1}, () => Array(k+1).fill(-1));
  for (let i = 1; i <= n; i++) {
    for (let t = 1; t <= k; t++) {
      let best = dp[i-1][t];
      let bestJ = -1;
      for (let j = 1; j <= i; j++) {
        const val = maxSub[j-1][i-1] + dp[j-1][t-1];
        if (val > best) { best = val; bestJ = j; }
      }
      dp[i][t] = best; take[i][t] = bestJ;
    }
  }
  const res = [];
  let i = n, t = k;
  while (t > 0 && i > 0) {
    const j = take[i][t];
    if (j === -1) break;
    res.push([j-1, i-1]);
    i = j - 1;
    t--;
  }
  res.reverse();
  return {value: dp[n][k], subarrays: res};
}
```

## Why This Is Asked
Tests DP partitioning with a non-sum objective and reconstruction requirements.

## Key Concepts
- DP over partitions with dp[i][t]
- Precomputing max-min for all subarrays
- Path reconstruction via parent pointers

## Code Example
```javascript
function maxMinSubarrayVal(arr){
  const n = arr.length;
  const maxVal = Array.from({length:n}, ()=>Array(n).fill(0));
  const minVal = Array.from({length:n}, ()=>Array(n).fill(0));
  for(let i=0;i<n;i++){
    let curMax = arr[i], curMin = arr[i];
    for(let j=i;j<n;j++){
      curMax = Math.max(curMax, arr[j]);
      curMin = Math.min(curMin, arr[j]);
      maxVal[i][j] = curMax;
      minVal[i][j] = curMin;
    }
  }
  const val = (l,r)=> maxVal[l][r] - minVal[l][r];
  return val;
}

function bestPartition(arr, k){
  const n = arr.length;
  const val = maxMinSubarrayVal(arr);
  const dp = Array.from({length:n+1}, ()=>Array(k+1).fill(-Infinity));
  const parent = Array.from({length:n+1}, ()=>Array(k+1).fill(-1));
  for(let i=1;i<=n;i++) dp[i][1] = val(0,i-1);
  for(let t=2;t<=k;t++){
    for(let i=t;i<=n;i++){
      for(let j=t-1;j<=i-1;j++){
        const cand = dp[j][t-1] + val(j, i-1);
        if(cand > dp[i][t]){ dp[i][t] = cand; parent[i][t]=j; }
      }
    }
  }
  // reconstruct
  let blocks = [];
  let i=n, t=k;
  while(t>0){
    const j = parent[i][t];
    blocks.push([j, i-1]);
    i = j; t--;
  }
  blocks.reverse();
  return {value: dp[n][k], blocks};
}
```

